DO $$
DECLARE t record; others bigint; n integer:=0;
BEGIN
 IF NOT private.is_member() THEN RAISE EXCEPTION '[REDACTED_LITERAL]'; END IF;
 FOR t IN
  SELECT c.table_schema,c.table_name
  FROM information_schema.columns c JOIN pg_namespace ns ON ns.nspname=c.table_schema
  JOIN pg_class tbl ON tbl.relnamespace=ns.oid AND tbl.relname=c.table_name
  WHERE c.table_schema='[REDACTED_LITERAL]' AND c.column_name='[REDACTED_LITERAL]' AND tbl.relrowsecurity
    AND tbl.relkind IN ('[REDACTED_LITERAL]','[REDACTED_LITERAL]')
    AND has_table_privilege('[REDACTED_LITERAL]',tbl.oid,'[REDACTED_LITERAL]')
    AND EXISTS (SELECT 1 FROM pg_policy pol WHERE pol.polrelid=tbl.oid AND pol.polname='[REDACTED_LITERAL]')
  ORDER BY c.table_name
 LOOP
  EXECUTE format('[REDACTED_LITERAL]',t.table_schema,t.table_name) INTO others;
  IF others<>0 THEN RAISE EXCEPTION '[REDACTED_LITERAL]',t.table_schema,t.table_name,others; END IF;
  n:=n+1;
 END LOOP;
 IF n<10 THEN RAISE EXCEPTION '[REDACTED_LITERAL]',n; END IF;
END $$

